solution.code:
public class Main {
    public static void main(String[] args) {
        for (int i = 1; i <= 4; i++) {
            StringBuilder line = new StringBuilder();
            for (int s = 0; s < 4 - i; s++) {
                line.append(' ');
            }
            for (int k = 0; k < 2 * i - 1; k++) {
                line.append('*');
            }
            System.out.println(line);
        }
    }
}
